import{t as e}from"./settlementLearning-BNFvsZJn.js";function t(t,n=10){let r=Array.from({length:n},(e,t)=>({bucket:t,min:t/n,max:(t+1)/n,rows:[]}));for(let e of t){let t=Math.max(0,Math.min(.999999,e.predicted));r[Math.min(n-1,Math.floor(t*n))].rows.push(e)}return r.map(t=>{let n=t.rows.length,r=t.rows.reduce((t,n)=>t+e(n.features).evidenceWeight,0),i=Math.max(1e-4,r),a=n?t.rows.reduce((t,n)=>t+n.predicted*e(n.features).evidenceWeight,0)/i:0,o=n?t.rows.reduce((t,n)=>t+n.outcome*e(n.features).evidenceWeight,0)/i:0,s=a-o,c=Math.abs(s)<.025?`CALIBRATED`:s>0?`OVERCONFIDENT`:`UNDERCONFIDENT`;return{bucket:t.bucket,min:t.min,max:t.max,sampleSize:n,effectiveSampleSize:r,predicted:a,actual:o,error:s,direction:c}})}function n(e){let n=t(e),r=n.filter(e=>e.sampleSize>0),i=r.reduce((e,t)=>e+t.effectiveSampleSize,0),a=Math.max(1e-4,i),o=i?r.reduce((e,t)=>e+Math.abs(t.error)*t.effectiveSampleSize,0)/a:0,s=r.filter(e=>e.direction===`OVERCONFIDENT`).reduce((e,t)=>e+t.sampleSize,0),c=r.filter(e=>e.direction===`UNDERCONFIDENT`).reduce((e,t)=>e+t.sampleSize,0);return{sampleSize:e.length,effectiveSampleSize:i,meanAbsoluteCalibrationError:o,overconfidentSamples:s,underconfidentSamples:c,buckets:n}}export{n,t};